void swap(int *a, int *b) {
  int m = *a;
  *a = *b;
  *b = m;
}

int factorial(int num) {
  int ans = 1;
  if (num >= 2) {
    for (int i = 2; i <= num; i++) {
      ans = ans * i;
    }
  }
  return ans;
}

int **ans;
int _index = 0;

void perm(int *array, int begin, int length) {
  if (begin == length - 1) {
    for (int i = 0; i < length; i++) {
      ans[_index][i] = array[i];
    }
    _index++;
  } else {
    for (int i = begin; i < length; i++) {
      swap(array + begin, array + i);
      perm(array, begin + 1, length);
      swap(array + begin, array + i);
    }
  }
}

int **permute(int *nums, int numsSize, int *returnSize, int **returnColumnSizes) {
  *returnSize = factorial(numsSize);
  *returnColumnSizes = (int *)malloc(sizeof(int) * *returnSize);
  ans = (int **)malloc(sizeof(int *) * factorial(numsSize));
  for (int i = 0; i < *returnSize; i++) {
    (*returnColumnSizes)[i] = numsSize;
    ans[i] = (int *)malloc(sizeof(int) * numsSize);
  }
  perm(nums, 0, numsSize);
  return ans;
}

class Solution {
public:
  void backtrack(vector<vector<int>> &res, vector<int> &output, int first, int len) {
    // 所有数都填完了
    if (first == len) {
      res.emplace_back(output);
      return;
    }
    for (int i = first; i < len; ++i) {
      // 动态维护数组
      swap(output[i], output[first]);
      // 继续递归填下一个数
      backtrack(res, output, first + 1, len);
      // 撤销操作
      swap(output[i], output[first]);
    }
  }
  vector<vector<int>> permute(vector<int> &nums) {
    vector<vector<int>> res;
    backtrack(res, nums, 0, (int)nums.size());
    return res;
  }
};

class Solution {
  private void backtrack(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> res) {
    if (cur.size() == nums.length) {
      res.add(new ArrayList<>(cur));
      return;
    }
    for (int i = 0; i < nums.length; i++) {
      if (used[i]) {
        continue;
      }
      used[i] = true;
      cur.add(nums[i]);
      backtrack(nums, used, cur, res);
      cur.remove(cur.size() - 1);
      used[i] = false;
    }
  }

  public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, new boolean[nums.length], new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        res = []
        used = [False] * len(nums)
        cur = []

        def backtrack():
            if len(cur) == len(nums):
                res.append(cur[:])
                return
            for i in range(len(nums)):
                if used[i]:
                    continue
                used[i] = True
                cur.append(nums[i])
                backtrack()
                cur.pop()
                used[i] = False

        backtrack()
        return res

impl Solution {
  pub fn permute(nums: Vec<i32>) -> Vec<Vec<i32>> {
    fn backtrack(nums: &[i32], used: &mut Vec<bool>, cur: &mut Vec<i32>, res: &mut Vec<Vec<i32>>) {
      if cur.len() == nums.len() {
        res.push(cur.clone());
        return;
      }
      for i in 0..nums.len() {
        if used[i] {
          continue;
        }
        used[i] = true;
        cur.push(nums[i]);
        backtrack(nums, used, cur, res);
        cur.pop();
        used[i] = false;
      }
    }
    let mut res = vec![];
    let mut cur = vec![];
    let mut used = vec![false; nums.len()];
    backtrack(&nums, &mut used, &mut cur, &mut res);
    res
  }
}

const permute = (nums: number[]): number[][] => {
  const res: number[][] = [];
  const used = new Array(nums.length).fill(false);
  const cur: number[] = [];

  const backtrack = () => {
    if (cur.length === nums.length) {
      res.push([...cur]);
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      cur.push(nums[i]);
      backtrack();
      cur.pop();
      used[i] = false;
    }
  };

  backtrack();
  return res;
};
